body:
I'd say we should make specifically `is_instance_id_valid` not error, but `instance_from_id` should still error as you are trying to do something that's arguably wrong and an error message helps, compare with `Node.has_node` and `Node.get_node` (with the added version `get_node_or_null`)

A new check for just validity would be something like:
```cpp
_ALWAYS_INLINE_ static bool has_instance(ObjectID p_instance_id) {
	uint64_t id = p_instance_id;
	uint32_t slot = id & OBJECTDB_SLOT_MAX_COUNT_MASK;

	if (slot >= slot_max) {
		return false;
	}

	spin_lock.lock();

	uint64_t validator = (id >> OBJECTDB_SLOT_MAX_COUNT_BITS) & OBJECTDB_VALIDATOR_MASK;

	if (unlikely(object_slots[slot].validator != validator)) {
		spin_lock.unlock();
		return false;
	}

	Object *object = object_slots[slot].object;

	spin_lock.unlock();

	return object != nullptr;
}
```

Though that could probably be simplified if we assume no entry with a correct validator is ever `nullptr`:
```cpp
_ALWAYS_INLINE_ static bool has_instance(ObjectID p_instance_id) {
	uint64_t id = p_instance_id;
	uint32_t slot = id & OBJECTDB_SLOT_MAX_COUNT_MASK;

	if (slot >= slot_max) {
		return false;
	}

	spin_lock.lock();

	uint64_t validator = (id >> OBJECTDB_SLOT_MAX_COUNT_BITS) & OBJECTDB_VALIDATOR_MASK;

	bool valid = object_slots[slot].validator == validator;

	spin_lock.unlock();

	return valid;
}
```
